// Colourful Thin Spiral, mla, 2023
// Draw as thin a spiral as possible, while minimizing
// aliasing artefacts. This one has colours and uses gamma
// correction as it makes colour bands wider and helps
// reduce artefacts.
//
// Colour palette is just an oblique line through RGB space.
//
// 'c': colours
// 'x': gamma
// 't': triangle wave (+ smoothstep)
// 'z': disable mouse control

float spiral = 2.0; // Number of arms on spiral, 0 for no spiral
float scale = 1.0;  // This can be any value in fact
float k = 0.55;     // Magic number, can be set with mouse-x

vec3 palette(float t) {
  vec3 col = t*vec3(0.414,0.618,1);
  col = mod(col,2.0);
  col = min(col,2.0-col);
  //col = hsv2rgb(col);
  if (!key(CHAR_X)) col *= col;
  return col;
}

float wave(float t) {
  if (!key(CHAR_T)) return 0.5*(1.0-cos(TWOPI*t));
  // Triangle wave + smoothstep - without smoothing not enough
  // at top and bottom & worse aliasing. With smoothing, I can't
  // tell this from the cos curve though (smoothstep is a good
  // approximation to an offset cosine).
  t *= 2.0;
  t = mod(t,2.0);
  t = min(t,2.0-t);
  t = smoothstep(0.0,1.0,t); // Cubic smoothing
  return t;
}

void mainImage(out vec4 o, vec2 p) {
    if (!key(CHAR_Z) && iMouse.x > 1.0) k = iMouse.x/iResolution.x; // Set k from mouse
    p -= 0.5*iResolution.xy;
    p /= scale;
    float d = length(p);
    float px = fwidth(p.x); // Same as 1.0/scale
    float angle = spiral*atan(p.y,p.x)/TWOPI;
    float h = 0.5*k*d/px;
    h -= 1.0*iTime;
    h += angle;
    float h0 = h;
    h = floor(h);
    h -= angle;
    //h -= 1.0*iTime; // How fast colours travel in the spiral
    o = vec4(0.8);
    if (!key(CHAR_C)) o.rgb = palette(h);
    o *= wave(h0);
    //o *= 2.0/(1.0+o); // tone mapping
    float g = 0.4545;
    //if (iMouse.y > 0.0) g = iMouse.y/iResolution.y;
    if (!key(CHAR_X)) o = pow(o,vec4(g)); // Gamma correction if desired.
}

common_code:
bool alert = false;
void assert(bool b) { if (!b) alert = true; }

const float PI = 3.141592654;
const float TWOPI = 2.0*PI;

const int CHAR_A = 65;
const int CHAR_C = 67;
const int CHAR_T = 84;
const int CHAR_X = 88;
const int CHAR_Y = 89;
const int CHAR_Z = 90;

#define key(code) (texelFetch(iChannel3, ivec2((code),2),0).x != 0.0)

vec3 h2rgb(float h) {
  vec3 rgb = clamp( abs(mod(h*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );
  return rgb*rgb*(3.0-2.0*rgb); // cubic smoothing	
}

vec3 hsv2rgb(vec3 c) {
  vec3 rgb = clamp( abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),6.0)-3.0)-1.0, 0.0, 1.0 );
  rgb = rgb*rgb*(3.0-2.0*rgb); // cubic smoothing	
  return c.z * mix( vec3(1.0), rgb, c.y);
}
